INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WIuS9HwK5z8', 4, '{"title":"第20202323条・刺法论篇第七十二","description":"<p>5、木欲升而天柱窒抑之。木欲发郁亦须待时。当刺足厥阴之井。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202323,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、木欲升而天柱窒抑之。木欲发郁亦须待时。当刺足厥阴之井。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BWqkzBm5pMN', 4, '{"title":"第20202324条・刺法论篇第七十二","description":"<p>6、火欲升而天蓬窒抑之。火欲发郁亦须待时。君火相火同刺包络之荥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202324,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、火欲升而天蓬窒抑之。火欲发郁亦须待时。君火相火同刺包络之荥。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fpU2Iu1a3ST', 4, '{"title":"第20202325条・刺法论篇第七十二","description":"<p>7、土欲升而天冲窒抑之。土欲发郁亦须待时。当刺足太阴之俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202325,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、土欲升而天冲窒抑之。土欲发郁亦须待时。当刺足太阴之俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rDFKvZhwcT7', 4, '{"title":"第20202326条・刺法论篇第七十二","description":"<p>8、金欲升而天英窒抑之。金欲发郁亦须待时。当刺手太阴之经。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202326,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、金欲升而天英窒抑之。金欲发郁亦须待时。当刺手太阴之经。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KHorqNyFiPW', 4, '{"title":"第20202327条・刺法论篇第七十二","description":"<p>9、水欲升而天芮窒抑之。水欲发郁亦须待时。当刺足少阴之合。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、水欲升而天芮窒抑之。水欲发郁亦须待时。当刺足少阴之合。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nHBJvbtSLTp', 4, '{"title":"第20202328条・刺法论篇第七十二","description":"<p>10、帝曰：升之不前。可以预备。愿闻其降。可以先防。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202328,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、帝曰：升之不前。可以预备。愿闻其降。可以先防。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KSDBOVNy8UM', 4, '{"title":"第20202329条・刺法论篇第七十二","description":"<p>11、岐伯曰：既明其升。必达其降也。升降之道。皆可先治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202329,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、岐伯曰：既明其升。必达其降也。升降之道。皆可先治也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5WGUAol9n72', 4, '{"title":"第20202330条・刺法论篇第七十二","description":"<p>12、木欲降而地晶窒抑之。降而不入。抑之郁发。散而可得位。降而郁发。暴如天间之待时也。降而不下。郁可速矣。降可折其所胜也。当刺手太阴之所出。刺手阳明之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202330,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '12、木欲降而地晶窒抑之。降而不入。抑之郁发。散而可得位。降而郁发。暴如天间之待时也。降而不下。郁可速矣。降可折其所胜也。当刺手太阴之所出。刺手阳明之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aNCJUVr4g8B', 4, '{"title":"第20202331条・刺法论篇第七十二","description":"<p>13、火欲降而地玄窒抑之。降而不入。抑之郁发。散而可入。当折其所胜。可散其郁。当刺足少阴之所出。刺足太阳之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、火欲降而地玄窒抑之。降而不入。抑之郁发。散而可入。当折其所胜。可散其郁。当刺足少阴之所出。刺足太阳之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PsrMBfpqdsk', 4, '{"title":"第20202332条・刺法论篇第七十二","description":"<p>14、土欲降而地苍窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺足厥阴之所出。刺足少阳之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '14、土欲降而地苍窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺足厥阴之所出。刺足少阳之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RbbbaSF7gdc', 4, '{"title":"第20202333条・刺法论篇第七十二","description":"<p>15、金欲降而地彤窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺心包络所出。刺手少阳所入也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202333,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '15、金欲降而地彤窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺心包络所出。刺手少阳所入也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TyhEKQhNWaR', 4, '{"title":"第20202334条・刺法论篇第七十二","description":"<p>16、水欲降而地阜窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺足太阴之所出，刺足阳明之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '16、水欲降而地阜窒抑之。降而不下。抑之郁发。散而可入。当折其胜。可散其郁。当刺足太阴之所出，刺足阳明之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6cJTUygewTo', 4, '{"title":"第20202335条・刺法论篇第七十二","description":"<p>17、帝曰：五运之至。有前后与升降往来。有所承抑之。可得闻乎刺法？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '17、帝曰：五运之至。有前后与升降往来。有所承抑之。可得闻乎刺法？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e2Q6O1hvKPA', 4, '{"title":"第20202336条・刺法论篇第七十二","description":"<p>18、岐伯曰：当取其化源也。是故太过取之。不及资之。太过取之。次抑其郁。取其运之化源。令折郁气。不及资之。以扶运气。以避虚邪也。（资取之法令出《密语》。）</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '18、岐伯曰：当取其化源也。是故太过取之。不及资之。太过取之。次抑其郁。取其运之化源。令折郁气。不及资之。以扶运气。以避虚邪也。（资取之法令出《密语》。）', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8KqWHalu6BK', 4, '{"title":"第20202337条・刺法论篇第七十二","description":"<p>19、黄帝问曰：升降之刺。以知其要。愿闻司天未得迁正。使司化之失其常政。即万化之或其皆妄。然与民为病。可得先除。欲济群生。愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '19、黄帝问曰：升降之刺。以知其要。愿闻司天未得迁正。使司化之失其常政。即万化之或其皆妄。然与民为病。可得先除。欲济群生。愿闻其说。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vnCx3CqXDXS', 4, '{"title":"第20202338条・刺法论篇第七十二","description":"<p>20、岐伯稽首再拜曰：悉乎哉问！言其至理。圣念慈悯。欲济群生。臣乃尽陈斯道。可申洞微。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202338,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '20、岐伯稽首再拜曰：悉乎哉问！言其至理。圣念慈悯。欲济群生。臣乃尽陈斯道。可申洞微。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MBgKefayHX1', 4, '{"title":"第20202339条・刺法论篇第七十二","description":"<p>21、太阳复布。即厥阴不迁正。不迁正气塞于上。当泻足厥阴之所流。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '21、太阳复布。即厥阴不迁正。不迁正气塞于上。当泻足厥阴之所流。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tcr8qgucFUQ', 4, '{"title":"第20202340条・刺法论篇第七十二","description":"<p>22、厥阴复布。少阴不迁正。不迁正即气塞于上。当刺心包络脉之所流。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202340,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '22、厥阴复布。少阴不迁正。不迁正即气塞于上。当刺心包络脉之所流。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
