INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Y7uE6fimLc', 4, '{"title":"第20202343条・刺法论篇第七十二","description":"<p>25、少阳复布。则阳明不迁正。不迁正则气未通上。当刺手太阴之所流。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202343,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '25、少阳复布。则阳明不迁正。不迁正则气未通上。当刺手太阴之所流。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMX26G4bFIt', 4, '{"title":"第20202344条・刺法论篇第七十二","description":"<p>26、阳明复布。太阳不迁正。不迁正则复塞其气。当刺足少阴之所流。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202344,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '26、阳明复布。太阳不迁正。不迁正则复塞其气。当刺足少阴之所流。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D8VvHJmxtj1', 4, '{"title":"第20202345条・刺法论篇第七十二","description":"<p>27、帝曰：迁正不前。以通其要。愿闻不退。欲折其余。无令过失。可得明乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202345,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '27、帝曰：迁正不前。以通其要。愿闻不退。欲折其余。无令过失。可得明乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GW5fP5MSQ42', 4, '{"title":"第20202346条・刺法论篇第七十二","description":"<p>28、岐伯曰：气过有余。复作布正。 是名不退位也。使地气不得后化。新司天未可迁正。故复布化令如故也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202346,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '28、岐伯曰：气过有余。复作布正。 是名不退位也。使地气不得后化。新司天未可迁正。故复布化令如故也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vy72usMwek', 4, '{"title":"第20202347条・刺法论篇第七十二","description":"<p>29、巳亥之岁。天数有余。故厥阴不退位也。风行于上。木化布天。当刺足厥阴之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '29、巳亥之岁。天数有余。故厥阴不退位也。风行于上。木化布天。当刺足厥阴之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tp7WZe34mqi', 4, '{"title":"第20202348条・刺法论篇第七十二","description":"<p>30、子午之岁。天数有余。故少阴不退位也。热行于上。火余化布天。当刺手厥阴之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202348,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '30、子午之岁。天数有余。故少阴不退位也。热行于上。火余化布天。当刺手厥阴之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AEWOsqkMch7', 4, '{"title":"第20202349条・刺法论篇第七十二","description":"<p>31、丑未之岁。天数有余。故太阴不退位也。湿行于上。雨化布天。当刺足太阴之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202349,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '31、丑未之岁。天数有余。故太阴不退位也。湿行于上。雨化布天。当刺足太阴之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FY2LQuAISzY', 4, '{"title":"第20202350条・刺法论篇第七十二","description":"<p>32、寅申之岁。天数有余。故少阳不退位也。热行于上。火化布天。当刺手少阳之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202350,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '32、寅申之岁。天数有余。故少阳不退位也。热行于上。火化布天。当刺手少阳之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zosFkfkUTRo', 4, '{"title":"第20202351条・刺法论篇第七十二","description":"<p>33、卯酉之岁。天数有余。故阳明不退位也。金行于上。燥化布天。当刺手太阴之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202351,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '33、卯酉之岁。天数有余。故阳明不退位也。金行于上。燥化布天。当刺手太阴之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9w0dUMyEa19', 4, '{"title":"第20202352条・刺法论篇第七十二","description":"<p>34、辰戌之岁。天数有余。故太阳不退位也。寒行于上。凛水化布天。当刺足少阴之所入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202352,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '34、辰戌之岁。天数有余。故太阳不退位也。寒行于上。凛水化布天。当刺足少阴之所入。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gn5fx5NYV4t', 4, '{"title":"第20202353条・刺法论篇第七十二","description":"<p>35、故天地气逆。化成民病。以法刺之。预可平疴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202353,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '35、故天地气逆。化成民病。以法刺之。预可平疴。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tElmMxJuM2x', 4, '{"title":"第20202354条・刺法论篇第七十二","description":"<p>36、黄帝问曰：刚柔二干。失守其位。使天运之气皆虚乎？与民为病。可得平乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202354,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '36、黄帝问曰：刚柔二干。失守其位。使天运之气皆虚乎？与民为病。可得平乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ZQFRTTnK69', 4, '{"title":"第20202355条・刺法论篇第七十二","description":"<p>37、岐伯曰：深乎哉问！明其奥旨。天地迭移。三年化疫。是谓根之可见。必有逃门。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202355,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '37、岐伯曰：深乎哉问！明其奥旨。天地迭移。三年化疫。是谓根之可见。必有逃门。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FcTnyPRd1kH', 4, '{"title":"第20202356条・刺法论篇第七十二","description":"<p>38、假令甲子。刚柔失守。刚未正。柔孤而有亏。时序不令。即音律非从。如此三年。变大疫也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202356,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '38、假令甲子。刚柔失守。刚未正。柔孤而有亏。时序不令。即音律非从。如此三年。变大疫也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T583iqgUIvM', 4, '{"title":"第20202357条・刺法论篇第七十二","description":"<p>39、详其微甚。察其浅深。欲至而可刺。刺之当先补肾俞。次三日。可刺足太阴之所注。又有下位己卯不至。而甲子孤立者。次三年作土疠。其法补泻。一如甲子同法也。其刺以毕。又不须夜行及远行。令七日洁。清净斋戒。所有自来肾有久病者。可以寅时面向南。净神不乱思。闭气不息七遍。以引颈咽气顺之。如咽甚硬物。如此七遍后。饵舌下津令无数。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202357,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '39、详其微甚。察其浅深。欲至而可刺。刺之当先补肾俞。次三日。可刺足太阴之所注。又有下位己卯不至。而甲子孤立者。次三年作土疠。其法补泻。一如甲子同法也。其刺以毕。又不须夜行及远行。令七日洁。清净斋戒。所有自来肾有久病者。可以寅时面向南。净神不乱思。闭气不息七遍。以引颈咽气顺之。如咽甚硬物。如此七遍后。饵舌下津令无数。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O6DAlk90vzF', 4, '{"title":"第20202358条・刺法论篇第七十二","description":"<p>40、假令丙寅。刚柔失守。上刚干失守。下柔不可独主之。中水运非太过。不可执法而定之。布天有余。而失守上正。天地不合。即律吕音异。如此即天运失序。后三年变疫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202358,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '40、假令丙寅。刚柔失守。上刚干失守。下柔不可独主之。中水运非太过。不可执法而定之。布天有余。而失守上正。天地不合。即律吕音异。如此即天运失序。后三年变疫。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QGTOuClDCwO', 4, '{"title":"第20202359条・刺法论篇第七十二","description":"<p>41、详其微甚。差有大小。徐至即后三年。至甚即首三年。当先补心俞。次五日。可刺肾之所入。又有下位地甲子。辛巳柔不附刚。亦名失守。即地运皆虚。后三年变水疠。即刺法皆如此矣。其刺如毕。慎其大喜欲情于中。如不忌。即其气复散也。令静七日。心欲实。令少思。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202359,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '41、详其微甚。差有大小。徐至即后三年。至甚即首三年。当先补心俞。次五日。可刺肾之所入。又有下位地甲子。辛巳柔不附刚。亦名失守。即地运皆虚。后三年变水疠。即刺法皆如此矣。其刺如毕。慎其大喜欲情于中。如不忌。即其气复散也。令静七日。心欲实。令少思。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nBnP2g5FH6Q', 4, '{"title":"第20202360条・刺法论篇第七十二","description":"<p>42、假令庚辰。刚柔失守。上位失守。下位无合。乙庚金运。故非相招。布天未退。中运胜来。上下相错。谓之失守。姑洗林钟。商音不应也。如此则天运化易。三年变大疫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202360,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '42、假令庚辰。刚柔失守。上位失守。下位无合。乙庚金运。故非相招。布天未退。中运胜来。上下相错。谓之失守。姑洗林钟。商音不应也。如此则天运化易。三年变大疫。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jhT2YW9pwtw', 4, '{"title":"第20202361条・刺法论篇第七十二","description":"<p>43、详其天数。差有微甚。微即微。三年至。甚即甚。三年至。当先补肝俞。次三日。可刺肺之所行。刺毕。可静神七日。慎勿大怒。怒必真气却散之。又或在下地甲子乙未失守者。即乙柔干。即上庚独治之。亦名失守者。即天运孤主之。三年变疠。名曰金疠。其至待时也。详其地数之等差。亦推其微甚。可知迟速尔。诸位乙庚失守。刺法同。肝欲平。即勿怒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202361,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '43、详其天数。差有微甚。微即微。三年至。甚即甚。三年至。当先补肝俞。次三日。可刺肺之所行。刺毕。可静神七日。慎勿大怒。怒必真气却散之。又或在下地甲子乙未失守者。即乙柔干。即上庚独治之。亦名失守者。即天运孤主之。三年变疠。名曰金疠。其至待时也。详其地数之等差。亦推其微甚。可知迟速尔。诸位乙庚失守。刺法同。肝欲平。即勿怒。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JQO1y0y8i1a', 4, '{"title":"第20202362条・刺法论篇第七十二","description":"<p>44、假令壬午。刚柔失守。上壬未迁正。下丁独然。即虽阳年。亏及不同。上下失守。相招其有期。差之微甚。各有其数也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202362,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '44、假令壬午。刚柔失守。上壬未迁正。下丁独然。即虽阳年。亏及不同。上下失守。相招其有期。差之微甚。各有其数也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M00oxOkNLsY', 4, '{"title":"第20202363条・刺法论篇第七十二","description":"<p>45、律吕二角。失而不和。同音有日。微甚如见。三年大疫。当刺脾俞。次三日。可刺肝之所出也。刺毕。静神七日。勿大醉歌乐。其气复散。又勿饱食。勿食生物。欲令脾实。气无滞饱。无久坐。食无太酸。无食一切生物。宜甘宜淡。又或地下甲子。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202363,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '45、律吕二角。失而不和。同音有日。微甚如见。三年大疫。当刺脾俞。次三日。可刺肝之所出也。刺毕。静神七日。勿大醉歌乐。其气复散。又勿饱食。勿食生物。欲令脾实。气无滞饱。无久坐。食无太酸。无食一切生物。宜甘宜淡。又或地下甲子。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yduH7WFCw6S', 4, '{"title":"第20202364条・刺法论篇第七十二","description":"<p>46、丁酉失守其位。未得中司。即气不当位。下不与壬奉合者。亦名失守。非名合德。故柔不附刚。即地运不合。三年变疠。其刺法一如木疫之法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202364,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '46、丁酉失守其位。未得中司。即气不当位。下不与壬奉合者。亦名失守。非名合德。故柔不附刚。即地运不合。三年变疠。其刺法一如木疫之法。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7eResAzTrvX', 4, '{"title":"第20202365条・刺法论篇第七十二","description":"<p>47、假令戊申。刚柔失守。戊癸虽火运。阳年不太过也。上失其刚。柔地独主。其气不正。故有邪干。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202365,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '47、假令戊申。刚柔失守。戊癸虽火运。阳年不太过也。上失其刚。柔地独主。其气不正。故有邪干。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QKVgmkUGIAB', 4, '{"title":"第20202366条・刺法论篇第七十二","description":"<p>48、迭移其位。差有浅深。欲至将合。音律先同。如此天运失时。三年之中。火疫至矣。当刺肺俞。刺毕。静神七日。勿大悲伤也。悲伤即肺动。而真气复散也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202366,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '48、迭移其位。差有浅深。欲至将合。音律先同。如此天运失时。三年之中。火疫至矣。当刺肺俞。刺毕。静神七日。勿大悲伤也。悲伤即肺动。而真气复散也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zZgBpgdeu0r', 4, '{"title":"第20202367条・刺法论篇第七十二","description":"<p>49、人欲实肺者。要在息气也。又或地下甲子。癸亥失守者。即柔失守位也。即上失其刚也。即亦名戊癸不相合德者也。即运与地虚。后三年变疠。即名火疠。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202367,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '49、人欲实肺者。要在息气也。又或地下甲子。癸亥失守者。即柔失守位也。即上失其刚也。即亦名戊癸不相合德者也。即运与地虚。后三年变疠。即名火疠。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rlZ5YNfZiDx', 4, '{"title":"第20202368条・刺法论篇第七十二","description":"<p>50、是故立地五年。以明失守。以穷法刺。于是疫之与疠。即是上下刚柔之名也。穷归一体也。即刺疫法。只有五法。即总其诸位失守。故只归五行而统之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202368,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '50、是故立地五年。以明失守。以穷法刺。于是疫之与疠。即是上下刚柔之名也。穷归一体也。即刺疫法。只有五法。即总其诸位失守。故只归五行而统之也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7W7TOq1j56b', 4, '{"title":"第20202369条・刺法论篇第七十二","description":"<p>51、黄帝曰：余闻五疫之至。皆相染易。无问大小。病状相似。不施救疗。如何可得不相移易者？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202369,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '51、黄帝曰：余闻五疫之至。皆相染易。无问大小。病状相似。不施救疗。如何可得不相移易者？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cKkn1xHdDSN', 4, '{"title":"第20202370条・刺法论篇第七十二","description":"<p>52、岐伯曰：不相染者。正气存内。邪不可干。避其毒瓦斯。天牝从来。复得其往。气出于脑。即不邪干。气出于脑。即室先想。心如日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202370,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '52、岐伯曰：不相染者。正气存内。邪不可干。避其毒瓦斯。天牝从来。复得其往。气出于脑。即不邪干。气出于脑。即室先想。心如日。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5PYIfJX7Zvs', 4, '{"title":"第20202371条・刺法论篇第七十二","description":"<p>53、欲将入于疫室。先想青气自肝而出。左行于东。化作林木。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202371,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '53、欲将入于疫室。先想青气自肝而出。左行于东。化作林木。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jBw1kNqaKKr', 4, '{"title":"第20202372条・刺法论篇第七十二","description":"<p>54、次想白气自肺而出。右行于西。化作戈甲。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202372,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '54、次想白气自肺而出。右行于西。化作戈甲。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JGVn2y0Y7Ky', 4, '{"title":"第20202373条・刺法论篇第七十二","description":"<p>55、次想赤气自心而出。南行于上。化作焰明。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202373,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '55、次想赤气自心而出。南行于上。化作焰明。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
