INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NP27yYLnGsZ', 4, '{"title":"第20202378条・刺法论篇第七十二","description":"<p>60、又一法。于雨水日后。三浴以药泄汗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202378,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '60、又一法。于雨水日后。三浴以药泄汗。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V2OZr9CDbhz', 4, '{"title":"第20202379条・刺法论篇第七十二","description":"<p>61、又一法。小金丹方：辰砂二两。水磨雄黄一两。叶子雌黄一两。紫金半两。同入合中。外固了地一尺筑地实。不用炉。不须药制。用火二十斤煅之也。七日终。候冷七日取。次日出合子。埋药地中七日。取出顺日研之三日。炼白沙蜜为丸。如梧桐子大。每日望东吸日华气一口。冰水下一丸。和气咽之。服十粒。无疫干也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202379,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '61、又一法。小金丹方：辰砂二两。水磨雄黄一两。叶子雌黄一两。紫金半两。同入合中。外固了地一尺筑地实。不用炉。不须药制。用火二十斤煅之也。七日终。候冷七日取。次日出合子。埋药地中七日。取出顺日研之三日。炼白沙蜜为丸。如梧桐子大。每日望东吸日华气一口。冰水下一丸。和气咽之。服十粒。无疫干也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ol2BNPvgbGQ', 4, '{"title":"第20202380条・刺法论篇第七十二","description":"<p>62、黄帝问曰：人虚即神游失守位。使鬼神外干。是致夭亡。何以全真？愿闻刺法。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202380,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '62、黄帝问曰：人虚即神游失守位。使鬼神外干。是致夭亡。何以全真？愿闻刺法。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GFG2pVTA6yf', 4, '{"title":"第20202381条・刺法论篇第七十二","description":"<p>63、岐伯稽首再拜曰：昭乎哉问！谓神移失守。虽在其体。然不致死。或有邪干。故令夭寿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202381,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '63、岐伯稽首再拜曰：昭乎哉问！谓神移失守。虽在其体。然不致死。或有邪干。故令夭寿。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IH01LkN9zs9', 4, '{"title":"第20202382条・刺法论篇第七十二","description":"<p>64、只如厥阴失守。天以虚。人气肝虚。感天重虚。即魂游于上。邪干厥大气。身温犹可刺之。刺其足少阳之所过。次刺肝俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202382,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '64、只如厥阴失守。天以虚。人气肝虚。感天重虚。即魂游于上。邪干厥大气。身温犹可刺之。刺其足少阳之所过。次刺肝俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G3fO6N87yuq', 4, '{"title":"第20202383条・刺法论篇第七十二","description":"<p>65、人病心虚。又遇君相二火司天失守。感而三虚。遇火不及。黑尸鬼犯之。令人暴亡。可刺手少阳之所过。复刺心俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202383,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '65、人病心虚。又遇君相二火司天失守。感而三虚。遇火不及。黑尸鬼犯之。令人暴亡。可刺手少阳之所过。复刺心俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OBlrOTZFdu2', 4, '{"title":"第20202384条・刺法论篇第七十二","description":"<p>66、人脾病。又遇太阴司天失守。感而三虚。又遇土不及。青尸鬼邪犯之于人。令人暴亡。可刺足阳明之所过。复刺脾俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202384,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '66、人脾病。又遇太阴司天失守。感而三虚。又遇土不及。青尸鬼邪犯之于人。令人暴亡。可刺足阳明之所过。复刺脾俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zk5pbFac7CS', 4, '{"title":"第20202385条・刺法论篇第七十二","description":"<p>67、人肺病。遇阳明司天失守。感而三虚。又遇金不及。有赤尸鬼干人。令人暴亡。可刺手阳明之所过。复刺肺俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202385,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '67、人肺病。遇阳明司天失守。感而三虚。又遇金不及。有赤尸鬼干人。令人暴亡。可刺手阳明之所过。复刺肺俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T4f5OQQczbQ', 4, '{"title":"第20202386条・刺法论篇第七十二","description":"<p>68、人肾病。又遇太阳司天失守。感而三虚。又遇水运不及之年。有黄尸鬼干犯人正气。吸人神魂。致暴亡。可刺足太阳之所过。复刺肾俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202386,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '68、人肾病。又遇太阳司天失守。感而三虚。又遇水运不及之年。有黄尸鬼干犯人正气。吸人神魂。致暴亡。可刺足太阳之所过。复刺肾俞。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vg0yUA2FnF6', 4, '{"title":"第20202387条・刺法论篇第七十二","description":"<p>69、黄帝问曰：十二脏之相使。神失位。使神彩之不圆。恐邪干犯。治之可刺。愿闻其要。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202387,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '69、黄帝问曰：十二脏之相使。神失位。使神彩之不圆。恐邪干犯。治之可刺。愿闻其要。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ygH7e8w311', 4, '{"title":"第20202388条・刺法论篇第七十二","description":"<p>70、岐伯稽首再拜曰： 悉乎哉。问至理。道真宗。此非圣帝。焉究斯源。是谓气神合道。契符上天。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202388,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '70、岐伯稽首再拜曰： 悉乎哉。问至理。道真宗。此非圣帝。焉究斯源。是谓气神合道。契符上天。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2HWCKRvRmc6', 4, '{"title":"第20202389条・刺法论篇第七十二","description":"<p>71、心者。君主之官。神明出焉。可刺手少阴之源。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202389,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '71、心者。君主之官。神明出焉。可刺手少阴之源。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fzXaDsAZAgI', 4, '{"title":"第20202390条・刺法论篇第七十二","description":"<p>72、肺者。相傅之官。治节出焉。可刺手太阴之源。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202390,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '72、肺者。相傅之官。治节出焉。可刺手太阴之源。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pN2SoqiEUsz', 4, '{"title":"第20202391条・刺法论篇第七十二","description":"<p>73、肝者。将军之官。谋虑出焉。可刺足厥阴之源。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202391,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '73、肝者。将军之官。谋虑出焉。可刺足厥阴之源。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
