INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9ZfuIbU39OD', 4, '{"title":"第20202401条・刺法论篇第七十二","description":"<p>83、凡此十二官 者。不得相失也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '83、凡此十二官 者。不得相失也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3XqKtuDdF1H', 4, '{"title":"第20202402条・刺法论篇第七十二","description":"<p>84、是故刺法有全神养真之旨。亦法有修真之道。非治疾也。故要修养和神也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202402,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '84、是故刺法有全神养真之旨。亦法有修真之道。非治疾也。故要修养和神也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MEKjL7C06Tq', 4, '{"title":"第20202403条・刺法论篇第七十二","description":"<p>85、道贵常存。补神固根。精气不散。神守不分。然即神守而虽不去。亦能全真。人神不守。非达至真。至真之要。在乎天玄。神守天息。复入本元。命曰归宗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202403,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '85、道贵常存。补神固根。精气不散。神守不分。然即神守而虽不去。亦能全真。人神不守。非达至真。至真之要。在乎天玄。神守天息。复入本元。命曰归宗。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ej2KoTYQ0yd', 4, '{"title":"第20202404条・本病论篇第七十三","description":"<p>1、黄帝问曰：天元九窒。余已知之。愿闻气交。何名失守？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202404,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝问曰：天元九窒。余已知之。愿闻气交。何名失守？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3ptzrRScp3q', 4, '{"title":"第20202405条・本病论篇第七十三","description":"<p>2、岐伯曰：谓其上下升降。迁正退位。各有经论。上下各有不前。故名失守也。是故气交失易位。气交乃变。变易非常。即四时失序。万化不安。变民病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202405,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、岐伯曰：谓其上下升降。迁正退位。各有经论。上下各有不前。故名失守也。是故气交失易位。气交乃变。变易非常。即四时失序。万化不安。变民病也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BHbFuFW99QK', 4, '{"title":"第20202406条・本病论篇第七十三","description":"<p>3、帝曰：升降不前。愿闻其故。气交有变。何以明知？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202406,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：升降不前。愿闻其故。气交有变。何以明知？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('trzDRq6rXCK', 4, '{"title":"第20202407条・本病论篇第七十三","description":"<p>4、岐伯曰：昭乎问哉！明乎道矣。气交有变。是为天地机。但欲降而不得降者。地窒刑之。又有五运太过。而先天而至者。即交不前。但欲升而不得其升。中运抑之。但欲降而不得其降。中运抑之。于是有升之不前。降之不下者。有降之不下。升而至天者。有升降俱不前。作如此之分别。即气交之变。变之有异。常各各不同。灾有微甚者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202407,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '4、岐伯曰：昭乎问哉！明乎道矣。气交有变。是为天地机。但欲降而不得降者。地窒刑之。又有五运太过。而先天而至者。即交不前。但欲升而不得其升。中运抑之。但欲降而不得其降。中运抑之。于是有升之不前。降之不下者。有降之不下。升而至天者。有升降俱不前。作如此之分别。即气交之变。变之有异。常各各不同。灾有微甚者也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iHq8DemdJzP', 4, '{"title":"第20202408条・本病论篇第七十三","description":"<p>5、帝曰：愿闻气交遇会胜抑之由。变成民病。轻重何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202408,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '5、帝曰：愿闻气交遇会胜抑之由。变成民病。轻重何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gxx07pi4cHs', 4, '{"title":"第20202409条・本病论篇第七十三","description":"<p>6、岐伯曰：胜相会。抑伏使然。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202409,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '6、岐伯曰：胜相会。抑伏使然。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u6LZOmQYxPb', 4, '{"title":"第20202410条・本病论篇第七十三","description":"<p>7、是故辰戌之岁。木气升之。主逢天柱。胜而不前。又遇庚戌。金运先天。中运胜之。忽然不前。木运升天。金乃抑之。升而不前。即清生风少。肃杀于春。露霜复降。草木乃萎。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202410,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '7、是故辰戌之岁。木气升之。主逢天柱。胜而不前。又遇庚戌。金运先天。中运胜之。忽然不前。木运升天。金乃抑之。升而不前。即清生风少。肃杀于春。露霜复降。草木乃萎。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lFU2Cam1b05', 4, '{"title":"第20202411条・本病论篇第七十三","description":"<p>8、民病温疫早发。咽嗌乃干。四胁满。肢节皆痛。久而化郁。即大风摧拉。折陨鸣紊。民病卒中偏痹。手足不仁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202411,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '8、民病温疫早发。咽嗌乃干。四胁满。肢节皆痛。久而化郁。即大风摧拉。折陨鸣紊。民病卒中偏痹。手足不仁。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cyHBmu439Gp', 4, '{"title":"第20202412条・本病论篇第七十三","description":"<p>9、是故巳亥之岁。君火升天。主窒天蓬。胜之不前。又厥阴木迁正。则少阴未得升天。水运以至其中者。君火欲升。而中水运抑之。升之不前。即清寒复作。冷生旦暮。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202412,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '9、是故巳亥之岁。君火升天。主窒天蓬。胜之不前。又厥阴木迁正。则少阴未得升天。水运以至其中者。君火欲升。而中水运抑之。升之不前。即清寒复作。冷生旦暮。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t0MiSAGG03l', 4, '{"title":"第20202413条・本病论篇第七十三","description":"<p>10、民病伏阳。而内生烦热。心神惊悸。寒热间作。日久成郁。即暴热乃至。赤风肿翳。化疫。温疠暖作。赤气彰而化火疫。皆烦而躁渴。渴甚治之以泄之可止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202413,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '10、民病伏阳。而内生烦热。心神惊悸。寒热间作。日久成郁。即暴热乃至。赤风肿翳。化疫。温疠暖作。赤气彰而化火疫。皆烦而躁渴。渴甚治之以泄之可止。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VZ0MKXsRCUz', 4, '{"title":"第20202414条・本病论篇第七十三","description":"<p>11、是故子午之岁。太阴升天。主窒天冲。胜之不前。又或遇壬子。木运先天而至者。中木遇抑之也。升天不前。即风埃四起。时举埃昏。雨湿不化。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202414,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '11、是故子午之岁。太阴升天。主窒天冲。胜之不前。又或遇壬子。木运先天而至者。中木遇抑之也。升天不前。即风埃四起。时举埃昏。雨湿不化。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iSOG6eQGyIk', 4, '{"title":"第20202415条・本病论篇第七十三","description":"<p>12、民病风厥涎潮。偏痹不随。胀满。久而伏郁。即黄埃化疫也。民病夭亡。脸肢胕。黄胆满闭。湿令弗布。雨化乃微。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202415,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '12、民病风厥涎潮。偏痹不随。胀满。久而伏郁。即黄埃化疫也。民病夭亡。脸肢胕。黄胆满闭。湿令弗布。雨化乃微。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Al98hbU2e4s', 4, '{"title":"第20202416条・本病论篇第七十三","description":"<p>13、是故丑未之年。少阳升天。主窒天蓬。胜之不前。又或遇太阴未迁正者。即少阳未升天也。水运以至者。升天不前。即寒反布。凛冽如冬。水复涸。冰再结。暄暖乍作。冷复布之，寒暄不时。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202416,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '13、是故丑未之年。少阳升天。主窒天蓬。胜之不前。又或遇太阴未迁正者。即少阳未升天也。水运以至者。升天不前。即寒反布。凛冽如冬。水复涸。冰再结。暄暖乍作。冷复布之，寒暄不时。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3BouF0ydcqq', 4, '{"title":"第20202417条・本病论篇第七十三","description":"<p>14、民病伏阳在内。烦热生中。心神惊骇。寒热间争。以成久郁。即暴热乃生。赤风气瞳翳。化成郁疠。乃化作伏热内烦。痹而生厥。甚则血溢。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202417,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '14、民病伏阳在内。烦热生中。心神惊骇。寒热间争。以成久郁。即暴热乃生。赤风气瞳翳。化成郁疠。乃化作伏热内烦。痹而生厥。甚则血溢。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k00FfAGu0hz', 4, '{"title":"第20202418条・本病论篇第七十三","description":"<p>15、是故寅申之年。阳明升天。主窒天英。胜之不前。又或遇戊申戊寅。火运先天而至。金欲升天。火运抑之。升之不前。实时雨不降。西风数举。咸卤燥生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202418,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '15、是故寅申之年。阳明升天。主窒天英。胜之不前。又或遇戊申戊寅。火运先天而至。金欲升天。火运抑之。升之不前。实时雨不降。西风数举。咸卤燥生。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V57fg3Jd6xb', 4, '{"title":"第20202419条・本病论篇第七十三","description":"<p>16、民病上热。喘嗽血溢。久而化郁。即白埃翳雾。清生杀气。民病胁满悲伤。寒鼽嚏嗌干。手拆皮肤燥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202419,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '16、民病上热。喘嗽血溢。久而化郁。即白埃翳雾。清生杀气。民病胁满悲伤。寒鼽嚏嗌干。手拆皮肤燥。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vv1uOOe0uMh', 4, '{"title":"第20202420条・本病论篇第七十三","description":"<p>17、是故卯酉之年。太阳升天。主窒天芮。胜之不前。又遇阳明未迁正者。即太阳未升天也。土运以至。水欲升天。土运抑之。升之不前。即湿而热蒸。寒生两间。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202420,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '17、是故卯酉之年。太阳升天。主窒天芮。胜之不前。又遇阳明未迁正者。即太阳未升天也。土运以至。水欲升天。土运抑之。升之不前。即湿而热蒸。寒生两间。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pr5j0kxvglp', 4, '{"title":"第20202421条・本病论篇第七十三","description":"<p>18、民病注下。食不及化。久而成郁。冷来客热。冰雹卒至。民病厥逆而哕。热生于内。气痹于外。足胫酸疼。反生心悸懊热，暴烦而复厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202421,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '18、民病注下。食不及化。久而成郁。冷来客热。冰雹卒至。民病厥逆而哕。热生于内。气痹于外。足胫酸疼。反生心悸懊热，暴烦而复厥。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WbHgmuBH2ag', 4, '{"title":"第20202422条・本病论篇第七十三","description":"<p>19、黄帝曰：升之不前。余已尽知其旨。愿闻降之不下。可得明乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202422,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '19、黄帝曰：升之不前。余已尽知其旨。愿闻降之不下。可得明乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m8y98rEfQS5', 4, '{"title":"第20202423条・本病论篇第七十三","description":"<p>20、岐伯曰：悉乎哉问！是之谓天地微旨。可以尽陈斯道。所谓升已必降也。至天三年。次岁必降。降而入地。始为左间也。如此升降往来。命之六纪者矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202423,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '20、岐伯曰：悉乎哉问！是之谓天地微旨。可以尽陈斯道。所谓升已必降也。至天三年。次岁必降。降而入地。始为左间也。如此升降往来。命之六纪者矣。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jfd65MNXjTI', 4, '{"title":"第20202424条・本病论篇第七十三","description":"<p>21、是故丑未之岁。厥阴降地。主窒地玄。胜而不前。又或遇少阴未退位。即厥阴未降下。金运以至中。金运承之。降之未下。抑之变郁。木欲降下。金承之。降而不下。苍埃远见。白气承之。风举埃昏。清躁行杀。霜露复下。肃杀布令。久而不降。抑之化郁。即作风躁相伏。暄而反清。草木萌动。杀霜乃下。蛰虫未见。惧清伤脏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202424,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '21、是故丑未之岁。厥阴降地。主窒地玄。胜而不前。又或遇少阴未退位。即厥阴未降下。金运以至中。金运承之。降之未下。抑之变郁。木欲降下。金承之。降而不下。苍埃远见。白气承之。风举埃昏。清躁行杀。霜露复下。肃杀布令。久而不降。抑之化郁。即作风躁相伏。暄而反清。草木萌动。杀霜乃下。蛰虫未见。惧清伤脏。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JWUgWfT1l2Q', 4, '{"title":"第20202425条・本病论篇第七十三","description":"<p>22、是故寅申之岁。少阴降地。主窒地玄。胜之不入。又或遇丙申丙寅。水运太过。先天而至。君火欲降。水运承之。降而不下。即彤云才见。黑气反生。暄暖如舒。寒常布雪。凛冽复作。天云惨凄。久而不降。伏之化郁。寒胜复热。赤风化疫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202425,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '22、是故寅申之岁。少阴降地。主窒地玄。胜之不入。又或遇丙申丙寅。水运太过。先天而至。君火欲降。水运承之。降而不下。即彤云才见。黑气反生。暄暖如舒。寒常布雪。凛冽复作。天云惨凄。久而不降。伏之化郁。寒胜复热。赤风化疫。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kq6pmk6vCsz', 4, '{"title":"第20202426条・本病论篇第七十三","description":"<p>23、民病面赤心烦。头痛目眩也。赤气彰而温病欲作也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202426,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '23、民病面赤心烦。头痛目眩也。赤气彰而温病欲作也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tQSsoAZsruQ', 4, '{"title":"第20202427条・本病论篇第七十三","description":"<p>24、是故卯酉之岁。太阴降地。主窒地苍。胜之不入。又或少阳未退位者。即太阴未得降也。或木运以至。木运承之。降而不下。即黄云见而青霞彰。郁蒸作而大风。雾翳埃胜。折损乃作。久而不降也。伏之化郁。天埃黄气。地布湿蒸。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202427,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '24、是故卯酉之岁。太阴降地。主窒地苍。胜之不入。又或少阳未退位者。即太阴未得降也。或木运以至。木运承之。降而不下。即黄云见而青霞彰。郁蒸作而大风。雾翳埃胜。折损乃作。久而不降也。伏之化郁。天埃黄气。地布湿蒸。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bjt3fTI9Bkq', 4, '{"title":"第20202428条・本病论篇第七十三","description":"<p>25、民病四肢不举。昏眩肢节痛。腹满填臆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202428,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '25、民病四肢不举。昏眩肢节痛。腹满填臆。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B8W3LBO5dWf', 4, '{"title":"第20202429条・本病论篇第七十三","description":"<p>26、是故辰戌之岁。少阳降地。主窒地玄。胜之不入。又或遇水运太过。先天而至也。水运承之。水降不下。即彤云才见。黑气反生。暄暖欲生。冷气卒至。甚即冰雹也。久而不降。伏之化郁。冷气复热。赤风化疫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202429,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '26、是故辰戌之岁。少阳降地。主窒地玄。胜之不入。又或遇水运太过。先天而至也。水运承之。水降不下。即彤云才见。黑气反生。暄暖欲生。冷气卒至。甚即冰雹也。久而不降。伏之化郁。冷气复热。赤风化疫。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LA4kgz2OxUG', 4, '{"title":"第20202430条・本病论篇第七十三","description":"<p>27、民病面赤心烦。头痛目眩也。赤气彰而热病欲作也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202430,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '27、民病面赤心烦。头痛目眩也。赤气彰而热病欲作也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J0JLBmi93RC', 4, '{"title":"第20202431条・本病论篇第七十三","description":"<p>28、是故巳亥之岁。阳明降地。主窒地彤。胜而不入。又或遇太阴未退位。即少阳未得降。即火运以至之。火运承之不下。即天清而肃。赤气乃彰。暄热反作。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202431,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '28、是故巳亥之岁。阳明降地。主窒地彤。胜而不入。又或遇太阴未退位。即少阳未得降。即火运以至之。火运承之不下。即天清而肃。赤气乃彰。暄热反作。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z962kVOHvDa', 4, '{"title":"第20202432条・本病论篇第七十三","description":"<p>29、民皆昏倦。夜卧不安。咽干引饮。懊热内烦。天清朝暮。暄还复作。久而不降。伏之化郁。天清薄寒。远生白气。民病掉眩。手足直而不仁。两胁作痛。满目䀮䀮。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202432,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '29、民皆昏倦。夜卧不安。咽干引饮。懊热内烦。天清朝暮。暄还复作。久而不降。伏之化郁。天清薄寒。远生白气。民病掉眩。手足直而不仁。两胁作痛。满目䀮䀮。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZrWbV6Y29Oo', 4, '{"title":"第20202433条・本病论篇第七十三","description":"<p>30、是故子午之年。太阳降地。主窒地阜胜之。降而不入。又或遇土运太过。先天而至。土运承之。降而不入。即天彰黑气。暝暗凄惨。才施黄埃而布湿。寒化令气。蒸湿复令。久而不降。伏之化郁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202433,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '30、是故子午之年。太阳降地。主窒地阜胜之。降而不入。又或遇土运太过。先天而至。土运承之。降而不入。即天彰黑气。暝暗凄惨。才施黄埃而布湿。寒化令气。蒸湿复令。久而不降。伏之化郁。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8O6uLJIxdxo', 4, '{"title":"第20202434条・本病论篇第七十三","description":"<p>31、民病大厥。四肢重怠。阴萎少力。天布沉阴。蒸湿间作。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202434,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '31、民病大厥。四肢重怠。阴萎少力。天布沉阴。蒸湿间作。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nVu9J9loMYU', 4, '{"title":"第20202435条・本病论篇第七十三","description":"<p>32、帝曰：升降不前。晰知其宗。愿闻迁正。可得明乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202435,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '32、帝曰：升降不前。晰知其宗。愿闻迁正。可得明乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bWBnUXANQED', 4, '{"title":"第20202436条・本病论篇第七十三","description":"<p>33、岐伯曰：正司中位。是谓迁正位。司天不得其迁正者。即前司天以过交司之日。即遇司天太过有余日也。即仍旧治天数。新司天未得迁正也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202436,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '33、岐伯曰：正司中位。是谓迁正位。司天不得其迁正者。即前司天以过交司之日。即遇司天太过有余日也。即仍旧治天数。新司天未得迁正也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c3QafYbxwpd', 4, '{"title":"第20202437条・本病论篇第七十三","description":"<p>34、厥阴不迁正。即风暄不时。花卉萎瘁。民病淋溲。目系转。转筋喜怒。小便赤。风欲令而寒由不去。温暄不正。春正失时。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202437,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '34、厥阴不迁正。即风暄不时。花卉萎瘁。民病淋溲。目系转。转筋喜怒。小便赤。风欲令而寒由不去。温暄不正。春正失时。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nGnwYfnL8k2', 4, '{"title":"第20202438条・本病论篇第七十三","description":"<p>35、少阴不迁正。即冷气不退。春冷后寒。暄暖不时。民病寒热。四肢烦痛。腰脊强直。木气虽有余。位不过于君火也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202438,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '35、少阴不迁正。即冷气不退。春冷后寒。暄暖不时。民病寒热。四肢烦痛。腰脊强直。木气虽有余。位不过于君火也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AwvQPchVy93', 4, '{"title":"第20202439条・本病论篇第七十三","description":"<p>36、太阴不迁正。即云雨失令。万物枯焦。当生不发。民病手足肢节肿满。大腹水肿。填臆不食。飧泄胁满。四肢不举。雨化欲令。热犹治之。温煦于气。亢而不泽。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202439,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '36、太阴不迁正。即云雨失令。万物枯焦。当生不发。民病手足肢节肿满。大腹水肿。填臆不食。飧泄胁满。四肢不举。雨化欲令。热犹治之。温煦于气。亢而不泽。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Uf1jNh2FTfS', 4, '{"title":"第20202440条・本病论篇第七十三","description":"<p>37、少阳不迁正。即炎灼弗令。苗莠不荣。酷暑于秋。肃杀晚至。霜露不时。民病痎疟骨热。心悸惊骇。甚时血溢。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202440,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '37、少阳不迁正。即炎灼弗令。苗莠不荣。酷暑于秋。肃杀晚至。霜露不时。民病痎疟骨热。心悸惊骇。甚时血溢。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('apcdfrp7zif', 4, '{"title":"第20202441条・本病论篇第七十三","description":"<p>38、阳明不迁正。则暑化于前。肃杀于后。草木反荣。民病寒热鼽嚏。皮毛折。爪甲枯焦。甚则喘嗽息高。悲伤不乐。热化乃布。燥化未令。即清劲未行。肺金复病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202441,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '38、阳明不迁正。则暑化于前。肃杀于后。草木反荣。民病寒热鼽嚏。皮毛折。爪甲枯焦。甚则喘嗽息高。悲伤不乐。热化乃布。燥化未令。即清劲未行。肺金复病。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QQwvXpfJizC', 4, '{"title":"第20202442条・本病论篇第七十三","description":"<p>39、太阳不迁正。即冬清反寒。易令于春。杀霜在前。寒冰于后。阳光复治。凛冽不作。氛云待时。民病温疠至。喉闭嗌干。烦燥而渴。喘息而有音也。寒化待燥。犹治天气。过失序。与民作灾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202442,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '39、太阳不迁正。即冬清反寒。易令于春。杀霜在前。寒冰于后。阳光复治。凛冽不作。氛云待时。民病温疠至。喉闭嗌干。烦燥而渴。喘息而有音也。寒化待燥。犹治天气。过失序。与民作灾。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ZLEzcpLuur', 4, '{"title":"第20202443条・本病论篇第七十三","description":"<p>40、帝曰：迁正早晚。以命其旨。愿闻退位。可得明哉？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202443,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '40、帝曰：迁正早晚。以命其旨。愿闻退位。可得明哉？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ElCLvvYfbWk', 4, '{"title":"第20202444条・本病论篇第七十三","description":"<p>41、岐伯曰：所谓不退者。即天数未终。即天数有余。名曰复布政。故名曰再治天也。即天令如故而不退位也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202444,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '41、岐伯曰：所谓不退者。即天数未终。即天数有余。名曰复布政。故名曰再治天也。即天令如故而不退位也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G0MNXwHZ2gc', 4, '{"title":"第20202445条・本病论篇第七十三","description":"<p>42、厥阴不退位。即大风早举。时雨不降。湿令不化。民病温疫。疵废风生。民病皆肢节痛。头目痛。伏热内烦。咽喉干引饮。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202445,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '42、厥阴不退位。即大风早举。时雨不降。湿令不化。民病温疫。疵废风生。民病皆肢节痛。头目痛。伏热内烦。咽喉干引饮。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('51PqHa9pU4C', 4, '{"title":"第20202446条・本病论篇第七十三","description":"<p>43、少阴不退位。即温生春冬。蛰虫早至。草木发生。民病膈热咽干。血溢惊骇。小便赤涩。丹瘤疮疡留毒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202446,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '43、少阴不退位。即温生春冬。蛰虫早至。草木发生。民病膈热咽干。血溢惊骇。小便赤涩。丹瘤疮疡留毒。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oKTAV4g0gxe', 4, '{"title":"第20202447条・本病论篇第七十三","description":"<p>44、太阴不退位。而取寒暑不时。埃昏布作。湿令不去。民病四肢少力。食饮不下。泄注淋满。足胫寒。阴萎闭塞。失溺小便数。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202447,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '44、太阴不退位。而取寒暑不时。埃昏布作。湿令不去。民病四肢少力。食饮不下。泄注淋满。足胫寒。阴萎闭塞。失溺小便数。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3wFUZmcPMY1', 4, '{"title":"第20202448条・本病论篇第七十三","description":"<p>45、少阳不退位。即热生于春。暑乃后化。冬温不冻。流水不冰。蛰虫出见。民病少气。寒热更作。便血上热。小腹坚满。小便赤沃。甚则血溢。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202448,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '45、少阳不退位。即热生于春。暑乃后化。冬温不冻。流水不冰。蛰虫出见。民病少气。寒热更作。便血上热。小腹坚满。小便赤沃。甚则血溢。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q22GoCf5oMs', 4, '{"title":"第20202449条・本病论篇第七十三","description":"<p>46、阳明不退位。即春生清冷。草木晚荣。寒热间作。民病呕吐暴注。食饮不下。大便干燥。四肢不举。目瞑掉眩。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202449,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '46、阳明不退位。即春生清冷。草木晚荣。寒热间作。民病呕吐暴注。食饮不下。大便干燥。四肢不举。目瞑掉眩。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lQDFiHDKMfR', 4, '{"title":"第20202450条・本病论篇第七十三","description":"<p>47、太阳不退位。即春寒复作。冰雹乃降。有昏翳。二之气寒犹不去。民病痹厥。阴痿失溺。腰膝皆痛。温疠晚发。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202450,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '47、太阳不退位。即春寒复作。冰雹乃降。有昏翳。二之气寒犹不去。民病痹厥。阴痿失溺。腰膝皆痛。温疠晚发。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bNrYQCyRxiq', 4, '{"title":"第20202451条・本病论篇第七十三","description":"<p>48、帝曰：天岁早晚。余以知之。愿闻地数。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202451,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '48、帝曰：天岁早晚。余以知之。愿闻地数。可得闻乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('82C4VwsI3N2', 4, '{"title":"第20202452条・本病论篇第七十三","description":"<p>49、岐伯曰：地下迁正升天及退位不前之法。即地土产化。 万物失时之化也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202452,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '49、岐伯曰：地下迁正升天及退位不前之法。即地土产化。 万物失时之化也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ns0gTO3dQrw', 4, '{"title":"第20202453条・本病论篇第七十三","description":"<p>50、帝曰：余闻天地二甲子。十干十二支。上下经纬天地。数有迭移。失守其位。可得昭乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202453,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '50、帝曰：余闻天地二甲子。十干十二支。上下经纬天地。数有迭移。失守其位。可得昭乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5KccRQysOSt', 4, '{"title":"第20202454条・本病论篇第七十三","description":"<p>51、岐伯曰：失之迭位者。谓虽得岁正。未得正位之司。即四时不节。即生大疫。注《玄珠密语》云：阳年三十年。除六年天刑。计有太过二十四年。除此六年。皆作太过之用。令不然之旨。今言迭支迭位。皆可作其不及也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202454,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '51、岐伯曰：失之迭位者。谓虽得岁正。未得正位之司。即四时不节。即生大疫。注《玄珠密语》云：阳年三十年。除六年天刑。计有太过二十四年。除此六年。皆作太过之用。令不然之旨。今言迭支迭位。皆可作其不及也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UxR8DXkCdVN', 4, '{"title":"第20202455条・本病论篇第七十三","description":"<p>52、假令甲子阳年。土运太窒。如癸亥天数有余者。年虽交得甲子。厥阴犹尚治天。地已迁正。阳明在泉。去岁少阳以作右间。即厥阴之地阳明。故不相和奉者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202455,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '52、假令甲子阳年。土运太窒。如癸亥天数有余者。年虽交得甲子。厥阴犹尚治天。地已迁正。阳明在泉。去岁少阳以作右间。即厥阴之地阳明。故不相和奉者也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kw9kguae3Ie', 4, '{"title":"第20202456条・本病论篇第七十三","description":"<p>53、癸巳相会。土运太过。虚反受木胜。故非太过也。何以言土运太过。况黄钟不应太窒。木既胜而金还复。金既复而少阴如至。即木胜如火而金复微。如此则甲己失守。后三年化成土疫。晚至丁卯。早至丙寅。土疫至也。大小善恶。推其天地。详乎太一。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202456,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '53、癸巳相会。土运太过。虚反受木胜。故非太过也。何以言土运太过。况黄钟不应太窒。木既胜而金还复。金既复而少阴如至。即木胜如火而金复微。如此则甲己失守。后三年化成土疫。晚至丁卯。早至丙寅。土疫至也。大小善恶。推其天地。详乎太一。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VYvzmkqF66k', 4, '{"title":"第20202457条・本病论篇第七十三","description":"<p>54、又只如甲子年。如甲至子而合。应交司而治天。即下己卯未迁正。而戊寅少阳未退位者。亦甲己下有合也。即土运非太过。而木乃乘虚而胜土也。金次又行复胜之。即反邪化也。阴阳天地殊异尔。故其大小善恶。一如天地之法旨也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202457,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '54、又只如甲子年。如甲至子而合。应交司而治天。即下己卯未迁正。而戊寅少阳未退位者。亦甲己下有合也。即土运非太过。而木乃乘虚而胜土也。金次又行复胜之。即反邪化也。阴阳天地殊异尔。故其大小善恶。一如天地之法旨也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bZhxByEGke4', 4, '{"title":"第20202458条・本病论篇第七十三","description":"<p>55、假令丙寅阳年太过。如乙丑天数有余者。虽交得丙寅。太阴尚治天也。地已迁正。厥阴司地。去岁太阳。以作右间。即天太阴而地厥阴。故地不奉天化也。乙辛相会。水运太虚。反受土胜。故非太过。即太簇之管。太羽不应。土胜而雨化。水复即风。此者丙辛失守其会。后三年化成水疫。晚至己巳。早至戊辰。甚即速。微即徐。水疫至也。大小善恶推其天地数。乃太乙游宫。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202458,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '55、假令丙寅阳年太过。如乙丑天数有余者。虽交得丙寅。太阴尚治天也。地已迁正。厥阴司地。去岁太阳。以作右间。即天太阴而地厥阴。故地不奉天化也。乙辛相会。水运太虚。反受土胜。故非太过。即太簇之管。太羽不应。土胜而雨化。水复即风。此者丙辛失守其会。后三年化成水疫。晚至己巳。早至戊辰。甚即速。微即徐。水疫至也。大小善恶推其天地数。乃太乙游宫。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Miwhe5n2T5', 4, '{"title":"第20202459条・本病论篇第七十三","description":"<p>56、又只如丙寅年。丙至寅且合。应交司而治天。即辛巳未得迁正。而庚辰太阳未退位者。亦丙辛不合德也。即水运亦小虚而小胜。或有复。后三年化疠。名曰水疠。其状如水疫。治法如前。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202459,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '56、又只如丙寅年。丙至寅且合。应交司而治天。即辛巳未得迁正。而庚辰太阳未退位者。亦丙辛不合德也。即水运亦小虚而小胜。或有复。后三年化疠。名曰水疠。其状如水疫。治法如前。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cctl9aXRul6', 4, '{"title":"第20202460条・本病论篇第七十三","description":"<p>57、假令庚辰阳年太过。如己卯天数有余者。虽交得庚辰年也。阳明犹尚治天。地已迁正。太阴司地。去岁少阴以作右间。即天阳明而地太阴也。故地下奉天也。乙巳相会。金运太虚。反受火胜。故非太过也。即姑洗之管。太商不应。火胜热化。水复寒刑。此乙庚失守。其后三年化成金疫也。速至壬午。徐至癸未。金疫至也。大小善恶。推本年天数及太一也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202460,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '57、假令庚辰阳年太过。如己卯天数有余者。虽交得庚辰年也。阳明犹尚治天。地已迁正。太阴司地。去岁少阴以作右间。即天阳明而地太阴也。故地下奉天也。乙巳相会。金运太虚。反受火胜。故非太过也。即姑洗之管。太商不应。火胜热化。水复寒刑。此乙庚失守。其后三年化成金疫也。速至壬午。徐至癸未。金疫至也。大小善恶。推本年天数及太一也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HNveLbO3wzZ', 4, '{"title":"第20202461条・本病论篇第七十三","description":"<p>58、又只如庚辰。如庚至辰。且应交司而治天。即下乙未未得迁正者。即地甲午少阴未退位者。且乙庚不合德也。即下乙未。干失刚。亦金运小虚也。有小胜或无复。后三年化疠。名曰金疠。其状如金疫也。治法如前。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202461,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '58、又只如庚辰。如庚至辰。且应交司而治天。即下乙未未得迁正者。即地甲午少阴未退位者。且乙庚不合德也。即下乙未。干失刚。亦金运小虚也。有小胜或无复。后三年化疠。名曰金疠。其状如金疫也。治法如前。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dyQhb3MA2jb', 4, '{"title":"第20202462条・本病论篇第七十三","description":"<p>59、假令壬午阳年太过。如辛巳天数有余者。虽交后壬午年也。厥阴犹尚治天。地已迁正。阳明在泉。去岁丙申少阳以作右间。即天厥阴而地阳明。故地不奉天者也。丁辛相合会。木运太虚。反受金胜。故非太过也。即蕤宾之管。太角不应。金行燥胜。火化热复。甚即速。微即徐。疫至大小善恶。推疫至之年天数及太一。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202462,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '59、假令壬午阳年太过。如辛巳天数有余者。虽交后壬午年也。厥阴犹尚治天。地已迁正。阳明在泉。去岁丙申少阳以作右间。即天厥阴而地阳明。故地不奉天者也。丁辛相合会。木运太虚。反受金胜。故非太过也。即蕤宾之管。太角不应。金行燥胜。火化热复。甚即速。微即徐。疫至大小善恶。推疫至之年天数及太一。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ko82qfxu6EH', 4, '{"title":"第20202463条・本病论篇第七十三","description":"<p>60、又只如壬至午。且应交司而治之。即下丁酉未得迁正者。即地下丙申少阳未得退位者。见丁壬不合德也。即丁柔干失刚。亦木运小虚也。有小胜小复。后三年化疠。名曰木疠。其状如风疫。法治如前。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202463,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '60、又只如壬至午。且应交司而治之。即下丁酉未得迁正者。即地下丙申少阳未得退位者。见丁壬不合德也。即丁柔干失刚。亦木运小虚也。有小胜小复。后三年化疠。名曰木疠。其状如风疫。法治如前。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IuLZ31U4Ks7', 4, '{"title":"第20202464条・本病论篇第七十三","description":"<p>61、假令戊申阳年太过。如丁未天数太过者。虽交得戊申年也。太阴犹尚治天。地已迁正。厥阴在泉。去岁壬戌太阳以退位作右间。即天丁未。地癸亥。故地不奉天化也。丁癸相会。火运太虚。反受水胜。故非太过也。即夷则之管。上太征不应。此戊癸失守其会。后三年化疫也。速至庚戌。大小善恶。推疫至之年天数及太一。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202464,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '61、假令戊申阳年太过。如丁未天数太过者。虽交得戊申年也。太阴犹尚治天。地已迁正。厥阴在泉。去岁壬戌太阳以退位作右间。即天丁未。地癸亥。故地不奉天化也。丁癸相会。火运太虚。反受水胜。故非太过也。即夷则之管。上太征不应。此戊癸失守其会。后三年化疫也。速至庚戌。大小善恶。推疫至之年天数及太一。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qEMy7NraLQq', 4, '{"title":"第20202465条・本病论篇第七十三","description":"<p>62、又只如戊申。如戊至申。且应交司而治天。即下癸亥未得迁正者。即地下壬戌太阳未退位者。见戊癸未合德也。即下癸柔干失刚。见火运小虚也。有小胜或无复也。后三年化疠。名曰火疠也。治法如前。治之法可寒之泄之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202465,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '62、又只如戊申。如戊至申。且应交司而治天。即下癸亥未得迁正者。即地下壬戌太阳未退位者。见戊癸未合德也。即下癸柔干失刚。见火运小虚也。有小胜或无复也。后三年化疠。名曰火疠也。治法如前。治之法可寒之泄之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FLNJolNsnzx', 4, '{"title":"第20202466条・本病论篇第七十三","description":"<p>63、黄帝曰：人气不足。天气如虚。人神失守。神光不聚。邪鬼干人。致有夭亡。可得闻乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202466,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '63、黄帝曰：人气不足。天气如虚。人神失守。神光不聚。邪鬼干人。致有夭亡。可得闻乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s3NIKANjGs1', 4, '{"title":"第20202467条・本病论篇第七十三","description":"<p>64、岐伯曰：人之五藏。一藏不足。又会天虚。感邪之至也。人忧愁思虑即伤心。又或遇少阴司天。天数不及。太阴作接间至。即谓天虚也。此即人气天气同虚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202467,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '64、岐伯曰：人之五藏。一藏不足。又会天虚。感邪之至也。人忧愁思虑即伤心。又或遇少阴司天。天数不及。太阴作接间至。即谓天虚也。此即人气天气同虚也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vchovOjN75P', 4, '{"title":"第20202468条・本病论篇第七十三","description":"<p>65、又遇惊而夺精。汗出于心。因而三虚。神明失守。心为君主之官。神明出焉。神失守位。即神游上丹田。在帝太一帝君泥丸宫下。神既失守。神光不聚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202468,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '65、又遇惊而夺精。汗出于心。因而三虚。神明失守。心为君主之官。神明出焉。神失守位。即神游上丹田。在帝太一帝君泥丸宫下。神既失守。神光不聚。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XrE3Hltjx51', 4, '{"title":"第20202469条・本病论篇第七十三","description":"<p>66、却遇火不及之岁。有黑尸鬼见之。令人暴亡。人饮食劳倦即伤脾。又或遇太阴司天。天数不及。即少阳作接间至。即谓之虚也。此即人气虚而天气虚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202469,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '66、却遇火不及之岁。有黑尸鬼见之。令人暴亡。人饮食劳倦即伤脾。又或遇太阴司天。天数不及。即少阳作接间至。即谓之虚也。此即人气虚而天气虚也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ve1Hf1YVqPK', 4, '{"title":"第20202470条・本病论篇第七十三","description":"<p>67、又遇饮食饱甚。汗出于胃。醉饱行房。汗出于脾。因而三虚。脾神失守。脾为谏议之官。智周出焉。神既失守。神光失位而不聚也。却遇土不及之年。或己年或甲年失守。或太阴天虚。青尸鬼见之，令人卒亡。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202470,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '67、又遇饮食饱甚。汗出于胃。醉饱行房。汗出于脾。因而三虚。脾神失守。脾为谏议之官。智周出焉。神既失守。神光失位而不聚也。却遇土不及之年。或己年或甲年失守。或太阴天虚。青尸鬼见之，令人卒亡。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RUqPUgA3173', 4, '{"title":"第20202471条・本病论篇第七十三","description":"<p>68、人久坐湿地。强力入水即伤肾。肾为作强之官。伎巧出焉。因而三虚。肾神失守。神志失位。神光不聚。却遇水不及之年。或辛不会符。或丙年失守。或太阳司天虚。有黄尸鬼至。见之令人暴亡。人或恚怒。气逆上而不下。即伤肝也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202471,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '68、人久坐湿地。强力入水即伤肾。肾为作强之官。伎巧出焉。因而三虚。肾神失守。神志失位。神光不聚。却遇水不及之年。或辛不会符。或丙年失守。或太阳司天虚。有黄尸鬼至。见之令人暴亡。人或恚怒。气逆上而不下。即伤肝也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XUymIu9yEdx', 4, '{"title":"第20202472条・本病论篇第七十三","description":"<p>69、又遇厥阴司天。天数不及。即少阴作接间至。是谓天虚也。此谓天虚人虚也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202472,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '69、又遇厥阴司天。天数不及。即少阴作接间至。是谓天虚也。此谓天虚人虚也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c6UJUe7A0WY', 4, '{"title":"第20202473条・本病论篇第七十三","description":"<p>70、又遇疾走恐惧。汗出于肝。肝为将军之官。谋虑出焉。神位失守。神光不聚。又遇木不及年。或丁年不符。或壬年失守。或厥阴司天虚也。有白尸鬼见之。令人暴亡也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202473,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '70、又遇疾走恐惧。汗出于肝。肝为将军之官。谋虑出焉。神位失守。神光不聚。又遇木不及年。或丁年不符。或壬年失守。或厥阴司天虚也。有白尸鬼见之。令人暴亡也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IbcbvgjLB9g', 4, '{"title":"第20202474条・本病论篇第七十三","description":"<p>71、以上五失守者。天虚而人虚也。神游失守其位。即有五尸鬼干人。令人暴亡也。谓之曰尸厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202474,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '71、以上五失守者。天虚而人虚也。神游失守其位。即有五尸鬼干人。令人暴亡也。谓之曰尸厥。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('byVFGm2PDHD', 4, '{"title":"第20202475条・本病论篇第七十三","description":"<p>72、人犯五神易位。 即神光不圆也。非但尸鬼。即一切邪犯者。皆是神失守位故也。此谓得守者生。失守者死。得神者昌。失神者亡。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202475,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '72、人犯五神易位。 即神光不圆也。非但尸鬼。即一切邪犯者。皆是神失守位故也。此谓得守者生。失守者死。得神者昌。失神者亡。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'El361DFyfMS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('poXYk3UKHaY', 4, '{"title":"第20202476条・至真要大论篇第七十四","description":"<p>1、黄帝问曰：五气交合。盈虚更作。余知之矣。六气分治。司天地者。其至何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202476,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝问曰：五气交合。盈虚更作。余知之矣。六气分治。司天地者。其至何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UOdyRu9YrAt', 4, '{"title":"第20202477条・至真要大论篇第七十四","description":"<p>2、岐伯再拜对曰：明乎哉问也！天地之大纪。人神之通应也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202477,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2、岐伯再拜对曰：明乎哉问也！天地之大纪。人神之通应也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Ls8l6k1uBt', 4, '{"title":"第20202478条・至真要大论篇第七十四","description":"<p>3、帝曰：愿闻上合昭昭。下合冥冥奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202478,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '3、帝曰：愿闻上合昭昭。下合冥冥奈何？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
