INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eYt2JuZ64e5', 4, '{"title":"第20202542条・至真要大论篇第七十四","description":"<p>67、民病胃脘当心而痛。上支两胁。膈咽不通。饮食不下。舌本强。食则呕。冷泄腹胀。溏泄瘕水闭。蛰虫不去。病本于脾。冲阳绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202542,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '67、民病胃脘当心而痛。上支两胁。膈咽不通。饮食不下。舌本强。食则呕。冷泄腹胀。溏泄瘕水闭。蛰虫不去。病本于脾。冲阳绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sw7Qnsjf7GY', 4, '{"title":"第20202543条・至真要大论篇第七十四","description":"<p>68、少阴司天。热淫所胜。怫热至。火行其政。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202543,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '68、少阴司天。热淫所胜。怫热至。火行其政。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fgp6BjzD0nf', 4, '{"title":"第20202544条・至真要大论篇第七十四","description":"<p>69、民病胸中烦热。嗌干。右胠满。皮肤痛。寒热咳喘。大雨且至。唾血血泄。鼽衄嚏呕。溺色变。甚则疮疡胕肿。肩背臂及缺盆中痛。心痛肺?䐜。腹大满。膨膨而喘咳。病本于肺。尺泽绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202544,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '69、民病胸中烦热。嗌干。右胠满。皮肤痛。寒热咳喘。大雨且至。唾血血泄。鼽衄嚏呕。溺色变。甚则疮疡胕肿。肩背臂及缺盆中痛。心痛肺?䐜。腹大满。膨膨而喘咳。病本于肺。尺泽绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NQbLgOsYq4U', 4, '{"title":"第20202545条・至真要大论篇第七十四","description":"<p>70、太阴司天。湿淫所胜。则沉阴且布。雨变枯槁。胕肿骨痛阴痹。阴痹者按之不得。腰脊头项痛。时眩。大便难。阴气不用。饥不欲食。咳唾则有血。心如悬。病本干肾。太溪绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202545,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '70、太阴司天。湿淫所胜。则沉阴且布。雨变枯槁。胕肿骨痛阴痹。阴痹者按之不得。腰脊头项痛。时眩。大便难。阴气不用。饥不欲食。咳唾则有血。心如悬。病本干肾。太溪绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N5mbtZQ2Ziu', 4, '{"title":"第20202546条・至真要大论篇第七十四","description":"<p>71、少阳司天。火淫所胜。则温气流行。金政不平。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202546,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '71、少阳司天。火淫所胜。则温气流行。金政不平。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XyPx8oJQz58', 4, '{"title":"第20202547条・至真要大论篇第七十四","description":"<p>72、民病头痛。发热恶寒而疟。热上皮肤痛。色变黄赤。传而为水。身面胕肿。腹满仰息。泄注赤白。疮疡咳唾血。烦心胸中热。甚则鼽衄。病本于肺。天府绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202547,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '72、民病头痛。发热恶寒而疟。热上皮肤痛。色变黄赤。传而为水。身面胕肿。腹满仰息。泄注赤白。疮疡咳唾血。烦心胸中热。甚则鼽衄。病本于肺。天府绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ydBi0sMtVSC', 4, '{"title":"第20202548条・至真要大论篇第七十四","description":"<p>73、阳明司天。燥淫所胜。则木乃晚荣。草乃晚生。筋骨内变。民病左胠胁痛。寒清于中。感而疟。咳。腹中鸣。注泄瞀溏。心胁暴痛。不可反侧。嗌干面尘。腰痛。丈夫疝。妇人少腹痛。目眛眦疡。疮痤痈。蛰虫来见。病本于肝。太冲绝，死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202548,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '73、阳明司天。燥淫所胜。则木乃晚荣。草乃晚生。筋骨内变。民病左胠胁痛。寒清于中。感而疟。咳。腹中鸣。注泄瞀溏。心胁暴痛。不可反侧。嗌干面尘。腰痛。丈夫疝。妇人少腹痛。目眛眦疡。疮痤痈。蛰虫来见。病本于肝。太冲绝，死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d8Hnc5U1rK7', 4, '{"title":"第20202549条・至真要大论篇第七十四","description":"<p>74、太阳司天。寒淫所胜。则寒气反至。水且冰。运火炎烈。雨暴乃雹。血变于中。发为痈疡。  民病厥心痛。呕血血泄鼽衄。善悲时眩仆。胸腹满。手热肘挛掖肿。心澹澹大动。胸胁胃脘不安。面赤目黄。善噫嗌干。甚则色炲。渴而欲饮。病本于心。神门绝。死不治。所谓动气。知其藏也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202549,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '74、太阳司天。寒淫所胜。则寒气反至。水且冰。运火炎烈。雨暴乃雹。血变于中。发为痈疡。 民病厥心痛。呕血血泄鼽衄。善悲时眩仆。胸腹满。手热肘挛掖肿。心澹澹大动。胸胁胃脘不安。面赤目黄。善噫嗌干。甚则色炲。渴而欲饮。病本于心。神门绝。死不治。所谓动气。知其藏也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Qm89xvCIUw8', 4, '{"title":"第20202550条・至真要大论篇第七十四","description":"<p>75、帝曰：善。治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202550,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '75、帝曰：善。治之奈何？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
