INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JglfLNaAArn', 4, '{"title":"第20202572条・至真要大论篇第七十四","description":"<p>97、岐伯曰：厥阴之胜。耳鸣头眩。愦愦欲吐。胃膈如寒。大风数举。倮虫不滋。胠胁气并。化而为热。小便黄赤。胃脘当心而痛。上支两胁。肠鸣飧泄。少腹痛。注下赤白。甚则呕吐。膈咽不通。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202572,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '97、岐伯曰：厥阴之胜。耳鸣头眩。愦愦欲吐。胃膈如寒。大风数举。倮虫不滋。胠胁气并。化而为热。小便黄赤。胃脘当心而痛。上支两胁。肠鸣飧泄。少腹痛。注下赤白。甚则呕吐。膈咽不通。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ihvl4wQwlxN', 4, '{"title":"第20202573条・至真要大论篇第七十四","description":"<p>98、少阴之胜。心下热善饥。脐下反动。气游三焦。炎暑至。木乃津。草乃萎。呕逆躁烦。腹满痛溏泄。传为赤沃。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202573,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '98、少阴之胜。心下热善饥。脐下反动。气游三焦。炎暑至。木乃津。草乃萎。呕逆躁烦。腹满痛溏泄。传为赤沃。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pV26Gu99Ia1', 4, '{"title":"第20202574条・至真要大论篇第七十四","description":"<p>99、太阴之胜。火气内郁。疮疡于中。流散于外。病在胠胁。甚则心痛热格。头痛喉痹项强。独胜则湿气内郁。寒迫下焦。痛留顶。互引眉间。胃满。雨数至。燥化乃见。少腹满。腰脽重强。内不便。善注泄。足下温。头重足胫胕肿。饮发于中。胕肿于上。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202574,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '99、太阴之胜。火气内郁。疮疡于中。流散于外。病在胠胁。甚则心痛热格。头痛喉痹项强。独胜则湿气内郁。寒迫下焦。痛留顶。互引眉间。胃满。雨数至。燥化乃见。少腹满。腰脽重强。内不便。善注泄。足下温。头重足胫胕肿。饮发于中。胕肿于上。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hWDKXBQ3YfW', 4, '{"title":"第20202575条・至真要大论篇第七十四","description":"<p>100、少阳之胜。热客于胃。烦心心痛。目赤欲呕。呕酸善饥。耳痛溺赤。善惊谵妄。暴热消烁。草萎水涸。介虫乃屈。少腹痛。下沃赤白。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202575,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '100、少阳之胜。热客于胃。烦心心痛。目赤欲呕。呕酸善饥。耳痛溺赤。善惊谵妄。暴热消烁。草萎水涸。介虫乃屈。少腹痛。下沃赤白。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v3zLImMVbwG', 4, '{"title":"第20202576条・至真要大论篇第七十四","description":"<p>101、阳明之胜。清发于中。左胠胁痛溏泄。内为嗌塞。外发（疒秃页）疝。大凉肃杀。华英改容。毛虫乃殃。胸中不便。嗌塞而咳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202576,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '101、阳明之胜。清发于中。左胠胁痛溏泄。内为嗌塞。外发（疒秃页）疝。大凉肃杀。华英改容。毛虫乃殃。胸中不便。嗌塞而咳。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('avFVUFYHRgz', 4, '{"title":"第20202577条・至真要大论篇第七十四","description":"<p>102、太阳之胜。凝栗且至。非时水冰。羽乃后化。痔疟发。寒厥入胃。则内生心痛。阴中乃疡。隐曲不利。互引阴股。筋肉拘苛。血脉凝泣。络满色变。或为血泄。皮肤痞肿。腹满食减。热反上行。头项囟顶脑户中痛。目如脱。寒入下焦。传为濡泻。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202577,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '102、太阳之胜。凝栗且至。非时水冰。羽乃后化。痔疟发。寒厥入胃。则内生心痛。阴中乃疡。隐曲不利。互引阴股。筋肉拘苛。血脉凝泣。络满色变。或为血泄。皮肤痞肿。腹满食减。热反上行。头项囟顶脑户中痛。目如脱。寒入下焦。传为濡泻。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
