INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NE8tXYLNl7B', 4, '{"title":"第20202587条・至真要大论篇第七十四","description":"<p>112、厥阴之复。少腹坚满。里急暴痛。偃木飞沙。倮虫不荣。厥心痛。汗发呕吐。饮食不入。入而复出。筋骨掉眩清厥。甚则入脾。食痹而吐。冲阳绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202587,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '112、厥阴之复。少腹坚满。里急暴痛。偃木飞沙。倮虫不荣。厥心痛。汗发呕吐。饮食不入。入而复出。筋骨掉眩清厥。甚则入脾。食痹而吐。冲阳绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('433i6NUhvvj', 4, '{"title":"第20202588条・至真要大论篇第七十四","description":"<p>113、少阴之复。燠热内作。烦躁鼽嚏。少腹绞痛。火见燔 焫。嗌燥。分注时止。气动于左。上行于右。咳。皮肤痛。暴喑心痛。郁冒不知人。乃洒淅恶寒。振栗谵妄。寒已而热。渴而欲饮。少气骨痿。隔肠不便。外为浮肿哕噫。赤气后化。流水不冰。热气大行。介虫不复。病胗疮疡。痈疽痤痔。甚则入肺。咳而鼻渊。天府绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202588,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '113、少阴之复。燠热内作。烦躁鼽嚏。少腹绞痛。火见燔 焫。嗌燥。分注时止。气动于左。上行于右。咳。皮肤痛。暴喑心痛。郁冒不知人。乃洒淅恶寒。振栗谵妄。寒已而热。渴而欲饮。少气骨痿。隔肠不便。外为浮肿哕噫。赤气后化。流水不冰。热气大行。介虫不复。病胗疮疡。痈疽痤痔。甚则入肺。咳而鼻渊。天府绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CyjxAts3gk3', 4, '{"title":"第20202589条・至真要大论篇第七十四","description":"<p>114、太阴之复。湿变乃举。体重中满。食饮不化。阴气上厥。胸中不便。饮发于中。咳喘有声。大雨时行。鳞见于陆。头顶痛重。而掉瘛尤甚。呕而密默。唾吐清液。甚则入肾。窍泻无度。太溪绝。死不 治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202589,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '114、太阴之复。湿变乃举。体重中满。食饮不化。阴气上厥。胸中不便。饮发于中。咳喘有声。大雨时行。鳞见于陆。头顶痛重。而掉瘛尤甚。呕而密默。唾吐清液。甚则入肾。窍泻无度。太溪绝。死不 治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xkkOHEOZkFA', 4, '{"title":"第20202590条・至真要大论篇第七十四","description":"<p>115、少阳之复。大热将至。枯燥燔倮。介虫乃耗。惊螈咳衄。心热烦躁。便数憎风。厥气上行。面如浮埃。目乃瞤瘛。火气内发。上为口糜呕逆。血溢血泄。发而为疟。恶寒鼓栗。寒极反热。嗌络焦槁。渴引水浆。色变黄赤。少气脉萎。化而为水。传为胕肿。甚则入肺。咳而血泄。尺泽绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202590,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '115、少阳之复。大热将至。枯燥燔倮。介虫乃耗。惊螈咳衄。心热烦躁。便数憎风。厥气上行。面如浮埃。目乃瞤瘛。火气内发。上为口糜呕逆。血溢血泄。发而为疟。恶寒鼓栗。寒极反热。嗌络焦槁。渴引水浆。色变黄赤。少气脉萎。化而为水。传为胕肿。甚则入肺。咳而血泄。尺泽绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hrPf0FitFm0', 4, '{"title":"第20202591条・至真要大论篇第七十四","description":"<p>116、阳明之复。清气大举。森木苍干。毛虫乃厉。病生胠胁。气归于左。善太息。甚则心痛痞满。腹胀而泄。呕苦咳哕烦心。病在膈中头痛。甚则入肝。惊骇筋挛。太冲绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202591,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '116、阳明之复。清气大举。森木苍干。毛虫乃厉。病生胠胁。气归于左。善太息。甚则心痛痞满。腹胀而泄。呕苦咳哕烦心。病在膈中头痛。甚则入肝。惊骇筋挛。太冲绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OXHkxhtGywx', 4, '{"title":"第20202592条・至真要大论篇第七十四","description":"<p>117、太阳之复。厥气上行。水凝雨冰。羽虫乃死。心胃生寒。胸膈不利。心痛痞满。头痛善悲。时眩仆。食减。腰脽反痛。屈伸不便。地裂冰坚。阳光不治。少腹控睾。引腰脊。上冲心。唾出清水。及为哕噫。甚则入心。善忘善悲。神门绝。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202592,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '117、太阳之复。厥气上行。水凝雨冰。羽虫乃死。心胃生寒。胸膈不利。心痛痞满。头痛善悲。时眩仆。食减。腰脽反痛。屈伸不便。地裂冰坚。阳光不治。少腹控睾。引腰脊。上冲心。唾出清水。及为哕噫。甚则入心。善忘善悲。神门绝。死不治。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
