INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zOtVWdemJVK', 4, '{"title":"第20202598条・至真要大论篇第七十四","description":"<p>123、阳明之复。治以辛温。佐以苦甘。以苦泄之。以苦下之。以酸补之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202598,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '123、阳明之复。治以辛温。佐以苦甘。以苦泄之。以苦下之。以酸补之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hDLKkJXyl7h', 4, '{"title":"第20202599条・至真要大论篇第七十四","description":"<p>124、太阳之复。治以咸热。佐以甘辛。以苦坚之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202599,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '124、太阳之复。治以咸热。佐以甘辛。以苦坚之。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UsCWEi88Yur', 4, '{"title":"第20202600条・至真要大论篇第七十四","description":"<p>125、治诸胜复。寒者热之。热者寒之。温者清之。清者温之。散者收之。抑者散之。燥者润之。急者缓之。坚者緛之。脆者坚之。衰者补之。强者泻之。各安其气。必清必静。则病气衰去。归其所宗。此治之大体也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202600,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '125、治诸胜复。寒者热之。热者寒之。温者清之。清者温之。散者收之。抑者散之。燥者润之。急者缓之。坚者緛之。脆者坚之。衰者补之。强者泻之。各安其气。必清必静。则病气衰去。归其所宗。此治之大体也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('me8TcjBVAgS', 4, '{"title":"第20202601条・至真要大论篇第七十四","description":"<p>126、帝曰：善。气之上下何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202601,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '126、帝曰：善。气之上下何谓也？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iOXscxVNdfu', 4, '{"title":"第20202602条・至真要大论篇第七十四","description":"<p>127、岐伯曰：身半以上。其气三矣。天之分也。天气主之。身半以下。其气三矣。地之分也。地气主之。以名命气。以气命处。而言其病。半。所谓天枢也。故上胜而下俱病者。以地名之。下胜而上俱病者。以天名之。所谓胜至。报气屈伏而未发也。复至则不以天地异名。皆如复气 为法也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202602,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '127、岐伯曰：身半以上。其气三矣。天之分也。天气主之。身半以下。其气三矣。地之分也。地气主之。以名命气。以气命处。而言其病。半。所谓天枢也。故上胜而下俱病者。以地名之。下胜而上俱病者。以天名之。所谓胜至。报气屈伏而未发也。复至则不以天地异名。皆如复气 为法也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DU4tMzHsLoM', 4, '{"title":"第20202603条・至真要大论篇第七十四","description":"<p>128、帝曰：胜复之动。时有常乎？气有必乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202603,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '128、帝曰：胜复之动。时有常乎？气有必乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1HnOMWyMYz1', 4, '{"title":"第20202604条・至真要大论篇第七十四","description":"<p>129、岐伯曰：时有常位。而气无必也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202604,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '129、岐伯曰：时有常位。而气无必也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZOki1z9Ubwz', 4, '{"title":"第20202605条・至真要大论篇第七十四","description":"<p>130、帝曰：愿闻其道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202605,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '130、帝曰：愿闻其道也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YeAMnHvXk1p', 4, '{"title":"第20202606条・至真要大论篇第七十四","description":"<p>131、岐伯曰：初气终三气。天气主之。胜之常也。四气尽终气。地气主之。复之常也。有胜则复。无胜则否。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202606,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '131、岐伯曰：初气终三气。天气主之。胜之常也。四气尽终气。地气主之。复之常也。有胜则复。无胜则否。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1InuV1z8MVK', 4, '{"title":"第20202607条・至真要大论篇第七十四","description":"<p>132、帝曰： 善。复已而胜何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202607,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '132、帝曰： 善。复已而胜何如？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M1Gm8IixnlW', 4, '{"title":"第20202608条・至真要大论篇第七十四","description":"<p>133、岐伯曰：胜至则复。无常数也。衰乃止耳。复已而胜。不复则害。此伤生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202608,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '133、岐伯曰：胜至则复。无常数也。衰乃止耳。复已而胜。不复则害。此伤生也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
