INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('au0RdmAw8p1', 4, '{"title":"第20202610条・至真要大论篇第七十四","description":"<p>135、岐伯曰：居非其位。不相得也。大复其胜则主胜之。故反病也。所谓火燥热也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202610,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '135、岐伯曰：居非其位。不相得也。大复其胜则主胜之。故反病也。所谓火燥热也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
