INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MoxwjeyHTep', 4, '{"title":"第20202612条・至真要大论篇第七十四","description":"<p>137、岐伯曰：夫气之胜也。微者随之。甚者制之。气之复也。和者平之。暴者夺之。皆随胜气。安其屈伏。无问其数。以平为期。此其道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202612,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '137、岐伯曰：夫气之胜也。微者随之。甚者制之。气之复也。和者平之。暴者夺之。皆随胜气。安其屈伏。无问其数。以平为期。此其道也。', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'vSWY2IuD1gN');
